 void render(){geometryKnown=false;ShowWindow(window,SW_HIDE);revoke();applicationBindings.clear();surface=nullptr;statusText=nullptr;statusFrame=nullptr;enabledToggle=nullptr;root=Grid{};root.RowSpacing(20);root.Padding({12,12,28,12});root.Background(dark?brush(18,24,32):brush(245,247,250));root.RequestedTheme(dark?ElementTheme::Dark:ElementTheme::Light);mount.Child(root);if(extensionEntry==L"bindings"){renderExtension();return;}RowDefinition header;header.Height({0,GridUnitType::Auto});root.RowDefinitions().Append(header);RowDefinition body;body.Height({1,GridUnitType::Star});root.RowDefinitions().Append(body);root.Children().Append(heading(settingsVisible?L"EQ 设置":L"通用 EQ",settingsVisible));if(settingsVisible){renderSettings();return;}RowDefinition footer;footer.Height({0,GridUnitType::Auto});root.RowDefinitions().Append(footer);surface=Border{};panel=card(surface,0);Grid::SetRow(panel,1);root.Children().Append(panel);statusText=text(L"等待音频回传",13);auto action=button(L"",[this]{connectionDialog();});action.Content(statusText);action.HorizontalAlignment(HorizontalAlignment::Stretch);action.HorizontalContentAlignment(HorizontalAlignment::Left);action.BorderThickness({0,0,0,0});action.Background(brush(0,0,0,0));statusFrame=card(action,14);Grid::SetRow(statusFrame,2);root.Children().Append(statusFrame);updateStatus();auto token=surface.LayoutUpdated([this](auto const&,auto const&){layout();});auto target=surface;handlers.push_back([target,token]{target.LayoutUpdated(token);});root.UpdateLayout();layout();}
 void layout()override{if(!root){PluginPage::layout();return;}if(settingsVisible||dialogVisible||!surface||!surface.IsLoaded()||surface.ActualHeight()<1){ShowWindow(window,SW_HIDE);return;}auto point=surface.TransformToVisual(root).TransformPoint({0,0});double scale=GetDpiForWindow(window)/96.0;RECT r{(LONG)std::lround(point.X*scale),(LONG)std::lround(point.Y*scale),(LONG)std::lround((point.X+surface.ActualWidth())*scale),(LONG)std::lround((point.Y+surface.ActualHeight())*scale)};int pane=(int)num(clipping,L"pane");RECT toast{(LONG)num(clipping,L"toastLeft"),(LONG)num(clipping,L"toastTop"),(LONG)num(clipping,L"toastRight"),(LONG)num(clipping,L"toastBottom")};bool changed=!geometryKnown||!EqualRect(&r,&lastEditorRect)||pane!=lastPane||!EqualRect(&toast,&lastToastRect);if(!changed){if(!IsWindowVisible(window))ShowWindow(window,SW_SHOWNOACTIVATE);return;}lastEditorRect=r;lastPane=pane;lastToastRect=toast;geometryKnown=true;SetWindowPos(editor->window,HWND_TOP,r.left,r.top,r.right-r.left,r.bottom-r.top,SWP_NOACTIVATE|SWP_SHOWWINDOW|SWP_NOREDRAW);auto region=CreateRectRgnIndirect(&r);if(pane){auto cut=CreateRectRgn(0,0,pane,r.bottom);CombineRgn(region,region,cut,RGN_DIFF);DeleteObject(cut);}if(num(clipping,L"toastRight")>num(clipping,L"toastLeft")){auto cut=CreateRectRgn((int)num(clipping,L"toastLeft"),(int)num(clipping,L"toastTop"),(int)num(clipping,L"toastRight"),(int)num(clipping,L"toastBottom"));CombineRgn(region,region,cut,RGN_DIFF);DeleteObject(cut);}if(!SetWindowRgn(window,region,FALSE))DeleteObject(region);if(!IsWindowVisible(window))ShowWindow(window,SW_SHOWNOACTIVATE);RedrawWindow(editor->window,nullptr,nullptr,RDW_INVALIDATE|RDW_ALLCHILDREN|RDW_UPDATENOW|RDW_NOERASE);}
 static std::wstring digits(double value,int places=0){wchar_t result[80]{};swprintf_s(result,L"%.*f",places,value);return result;}
 void markFeedback(Border frame,bool confirmed){if(!frame)return;frame.BorderBrush(confirmed?(dark?brush(48,59,73):brush(225,230,237)):brush(196,43,28));double width=confirmed?1:2;frame.BorderThickness({width,width,width,width});}
 void updateStatus(){if(!statusText)return;auto data=runtime();std::wstring status=flag(data,L"fxSoundConflict")?tr(L"FxSound 正在运行，Hhub EQ 已暂停让出共享驱动；退出 FxSound 后可继续使用"):flag(data,L"remoteSession")&&flag(data,L"driverInstalled")&&!flag(data,L"driverReady")?tr(L"曲线编辑可用 · 远程会话未暴露虚拟音频端点，实时应用处理未启动"):flag(data,L"driverReady")?tr(L"FxSound 共享虚拟音频端点已就绪"):flag(data,L"driverInstalled")?tr(L"驱动已安装，但当前会话没有可访问的虚拟音频端点；实时链路未启用"):tr(L"尚未安装虚拟音频路由驱动，处理链路不可启动");if(!flag(data,L"routingAvailable"))status+=tr(L"\n当前 Windows 不支持自动应用路由");for(auto const& v:data.GetNamedArray(L"streams",JsonArray{})){auto s=v.GetObject();if((app.empty()||str(s,L"app")==app)){status=tr(L"当前链路：")+str(s,L"state");if(!str(s,L"error").empty())status+=L"\n"+str(s,L"error");auto meter=[](double x){return x>0?digits(20*std::log10(x),1)+L" dBFS":std::wstring(L"−∞ dBFS");};status+=tr(L"\n输入峰值 ")+meter(num(s,L"inputPeak"))+tr(L"   输出峰值 ")+meter(num(s,L"outputPeak"))+tr(L"\n实际前级 ")+digits(num(s,L"preampDb"),1)+tr(L" dB · 限幅采样 ")+digits(num(s,L"limitedSamples"))+tr(L" · 欠载帧 ")+digits(num(s,L"underruns"));}}statusText.Text(status);bool acknowledged=false;for(auto const& v:data.GetNamedArray(L"streams",JsonArray{})){auto s=v.GetObject();if((app.empty()||str(s,L"app")==app)&&str(s,L"output")==output&&str(s,L"error").empty()&&num(s,L"frames")>0&&flag(s,L"acknowledged"))acknowledged=true;}if(true&&!flag(config,L"enabled",true)){bool pending=false;for(auto const& v:data.GetNamedArray(L"restorePending",JsonArray{}))if(std::wstring(v.GetString())==app)pending=true;acknowledged=!pending;status=pending?tr(L"原声输出恢复尚未通过回传，稍后会自动重试"):tr(L"已停止 EQ，应用输出恢复已回读");}if(dirty){status=tr(L"参数已调整，尚未应用。\n")+status;acknowledged=false;}statusText.Text(status);markFeedback(statusFrame,acknowledged||!flag(data,L"driverReady"));bool streamError=!str(data,L"nodeLifecycleError").empty();if(streamError){statusText.Text(str(data,L"nodeLifecycleError"));markFeedback(statusFrame,false);}for(auto const& value:data.GetNamedArray(L"streams",JsonArray{}))if(!str(value.GetObject(),L"error").empty())streamError=true;if(statusFrame)statusFrame.Visibility(flag(data,L"driverReady")&&!flag(data,L"fxSoundConflict")&&!streamError&&!dirty?Visibility::Collapsed:Visibility::Visible);}
