 void installDriver()override{driverDialog();}
 fire_and_forget driverDialog(){auto living=alive;ContentDialog dialog;dialog.XamlRoot(root.XamlRoot());dialog.RequestedTheme(root.RequestedTheme());dialog.Title(box_value(tr(L"安装 EQ 虚拟音频驱动")));dialog.Content(text(L"插件包包含 FxSound 官方签名虚拟音频驱动。\n\n实时音效需要安装此驱动，Windows 将请求管理员授权，部分电脑需要重启。请先退出 FxSound。\n\nHhub 仅处理你绑定的应用，保留物理输出设备。选择“稍后”仍可编辑和保存曲线。"));dialog.PrimaryButtonText(tr(L"安装驱动"));dialog.CloseButtonText(tr(L"稍后"));activeDialog=dialog;dialogVisible=true;layout();auto choice=co_await dialog.ShowAsync();if(!*living)co_return;activeDialog=nullptr;dialogVisible=false;if(choice==ContentDialogResult::Primary)PluginPage::installDriver();layout();}
