 void command(JsonObject data)override{auto action=str(data,L"action");if(action==L"layout"){clipping=data;layout();return;}if(action==L"connection"){connectionDialog();return;}if(action==L"driver"){driverDialog();return;}if(action==L"chooseApp"){wchar_t path[32768]{};OPENFILENAMEW picker{sizeof(picker)};picker.hwndOwner=GetAncestor(window,GA_ROOT);picker.lpstrFilter=L"应用程序 (*.exe)\0*.exe\0\0";picker.lpstrFile=path;picker.nMaxFile=32768;picker.Flags=OFN_FILEMUSTEXIST|OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR;if(GetOpenFileNameW(&picker)){JsonObject b;put(b,L"path",std::wstring(path));invoke(L"eqRegister",b);app=L"app:"+EqNode::upper(path);loadConfig();render();}return;}if(action==L"settings"){openSettings();return;}if(action==L"back"){settingsVisible=false;render();return;}if(action==L"savePreset"){savePreset(config);return;}PluginPage::command(data);render();}
